/* Generated by Org Museum; shared by exported pages. */

(function(){
function init(){
  var inp=document.getElementById('org-museum-search-input');if(!inp)return;
  var empty=document.querySelector('[data-sidebar-search-empty]');
  if(inp.addEventListener){
    inp.addEventListener('keydown',function(e){
      if(e.key==='Escape'&&this.value){
        e.stopPropagation();
        this.value='';
        this.dispatchEvent(new Event('input'));
      }
    });
  }
  inp.addEventListener('input',function(){
    var t=this.value.toLowerCase().trim();
    var matches=0;
    document.querySelectorAll('#org-museum-sidebar .sidebar-category').forEach(function(c){
      var visible=false;
      c.querySelectorAll('li a').forEach(function(a){
        if(!a.dataset.origText) a.dataset.origText = a.textContent;
        var txt = a.dataset.origText;
        var idx = txt.toLowerCase().indexOf(t);
        var show = !t || idx >= 0;
        a.parentElement.style.display = show ? '' : 'none';
        if(show){
          matches++;
          visible=true;
          if(t){
            var pre = txt.substring(0, idx);
            var hl = txt.substring(idx, idx+t.length);
            var post = txt.substring(idx+t.length);
            var mark=document.createElement('span');
            mark.className='search-highlight';mark.textContent=hl;
            a.replaceChildren(document.createTextNode(pre),mark,document.createTextNode(post));
          }else{
            a.textContent = txt;
          }
        }
      });
      c.style.display=visible?'':'none';
    });
    if(empty)empty.hidden=!t||matches>0;
  });
  try {
    var curFile = (location.pathname||'').split('/').pop() || 'index.html';
    document.querySelectorAll('#org-museum-sidebar .sidebar-category li a').forEach(function(a){
      var targetFile = (a.getAttribute('href')||'').split('/').pop();
      if(targetFile && targetFile === curFile){
        a.parentElement.classList.add('is-current-page');
        a.setAttribute('aria-current', 'page');
      }
    });
  } catch(e) {}
}
if(document.readyState==='loading')
  document.addEventListener('DOMContentLoaded',init);
else init();
})();

;

(function(){
'use strict';
var data=window.ORG_MUSEUM_RELATED_DATA||{pages:[],edges:[]};
var pages=new Map((data.pages||[]).map(function(page){return [page.id,page];}));
var params=new URLSearchParams(location.search);
var source=pages.get(params.get('source')||'');
var target=pages.get(params.get('target')||'');
var mode=params.get('mode')==='full'?'full':'summary';
var detail=document.getElementById('related-detail');
var index=document.getElementById('related-index');
var empty=document.getElementById('related-empty');
var search=document.getElementById('org-museum-global-search');
var positions={summary:[0,0],full:[0,0]};
var activePane='source',syncScroll=false,syncingScroll=false;

function themed(href){return window.orgMuseumThemeUrl?window.orgMuseumThemeUrl(href):href;}
function links(from,to){return !!from&&Array.isArray(from.linksTo)&&from.linksTo.includes(to.id);}
function relationValid(){return source&&target&&source.id!==target.id&&(links(source,target)||links(target,source));}
function setUrl(nextMode){
  var url=new URL(location.href);url.searchParams.set('source',source.id);
  url.searchParams.set('target',target.id);url.searchParams.set('mode',nextMode);
  history.pushState({},'',url.pathname+url.search+url.hash);
}
function element(tag,className,text){
  var node=document.createElement(tag);if(className)node.className=className;
  if(text!==undefined)node.textContent=text;return node;
}
function pageMeta(page){
  var meta=element('div','related-page-meta');
  meta.appendChild(element('span','related-category',page.categoryLabel||page.category||'未分类'));
  meta.appendChild(element('time','',page.modifiedDate||''));
  var textLen = (page.contentHtml||'').replace(/<[^>]+>/g,'').length;
  var estMin = Math.max(1, Math.round(textLen / 350));
  meta.appendChild(element('span','related-readtime','⏱ 约 '+estMin+' 分钟'));
  (page.tags||[]).forEach(function(tag){meta.appendChild(element('span','related-tag','#'+tag));});
  return meta;
}
function summaryContent(page, side){
  var root=element('div','related-summary');
  var summary=element('section','related-summary-block related-summary-prose');
  summary.appendChild(element('h2','', '摘要'));
  summary.appendChild(element('p','',page.description||'暂无可用摘要。'));root.appendChild(summary);
  var outline=element('section','related-summary-block related-summary-outline');
  outline.appendChild(element('h2','','章节大纲（点击可直达正文）'));
  var list=element('ol','related-outline');
  var headings = page.headings||[];
  if(headings.length){
    headings.forEach(function(item, idx){
      var li=element('li','');
      var btn=element('button','outline-jump-btn',item.title||'');
      btn.type='button';
      btn.title='点击跳转至完整正文此章节';
      btn.onclick=function(){
        updateMode('full',true);
        setTimeout(function(){
          var panel=document.querySelector('[data-related-panel="'+side+'"]');
          if(!panel||typeof panel.querySelectorAll!=='function')return;
          var heads=Array.from(panel.querySelectorAll('h2, h3, h4'));
          var targetHead=heads.find(function(h){return (h.textContent||'').trim()===(item.title||'').trim();})||heads[idx];
          if(targetHead){
            targetHead.scrollIntoView({behavior:'smooth',block:'start'});
            targetHead.classList.add('heading-jump-highlight');
            setTimeout(function(){targetHead.classList.remove('heading-jump-highlight');},2000);
          }
        },60);
      };
      li.appendChild(btn);
      list.appendChild(li);
    });
  } else {
    list.appendChild(element('li','related-muted','暂无章节标题'));
  }
  outline.appendChild(list);root.appendChild(outline);
  var excerpts=element('section','related-summary-block related-summary-excerpts');
  excerpts.appendChild(element('h2','','核心内容摘录'));
  (page.excerpts||[]).forEach(function(text){excerpts.appendChild(element('p','',text));});
  if(!(page.excerpts||[]).length)excerpts.appendChild(element('p','related-muted','暂无更多摘录。'));
  root.appendChild(excerpts);return root;
}
function updatePanelProgress(panel){
  var bar=panel.querySelector('.related-reading-progress span');
  var max=Math.max(1,panel.scrollHeight-panel.clientHeight);
  var ratio=Math.max(0,Math.min(1,panel.scrollTop/max));
  if(bar)bar.style.transform='scaleX('+ratio+')';
}
function bindPanelScroll(panel,index){
  updatePanelProgress(panel);
  panel.addEventListener('scroll',function(){
    positions[mode][index]=panel.scrollTop;updatePanelProgress(panel);
    if(!syncScroll||mode!=='full'||innerWidth<=820||syncingScroll)return;
    var peers=Array.from(document.querySelectorAll('.related-paper'));
    var other=peers[index===0?1:0];if(!other)return;
    var max=Math.max(1,panel.scrollHeight-panel.clientHeight);
    syncingScroll=true;other.scrollTop=(panel.scrollTop/max)*Math.max(0,other.scrollHeight-other.clientHeight);
    updatePanelProgress(other);requestAnimationFrame(function(){syncingScroll=false;});
  },{passive:true});
}
function setActivePane(value){
  activePane=value==='relation'?'relation':value==='target'?'target':'source';
  document.body.dataset.relatedPane=activePane;
  document.querySelectorAll('button[data-related-pane]').forEach(function(button){
    var active=button.dataset.relatedPane===activePane;
    button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',active?'true':'false');
  });
}
function renderPanel(side,page){
  var panel=document.querySelector('[data-related-panel="'+side+'"]');if(!panel)return;panel.textContent='';
  var progress=element('div','related-reading-progress');progress.setAttribute('aria-hidden','true');
  progress.appendChild(element('span',''));panel.appendChild(progress);
  var badge=element('span','related-role',side==='source'?'源笔记（出链）':'目标笔记（入链）');
  var heading=element('div','related-paper-heading');
  var headingTop=element('div','related-paper-heading-top');
  headingTop.appendChild(badge);
  var topOpen=element('a','related-card-open','新标签打开 ↗');
  topOpen.href=themed(page.href);
  topOpen.target='_blank';
  topOpen.title='在新标签页中打开完整笔记独立页面';
  headingTop.appendChild(topOpen);
  heading.appendChild(headingTop);
  heading.appendChild(element('h1','related-page-title',page.title));panel.appendChild(heading);
  panel.appendChild(pageMeta(page));
  if(mode==='full'){
    var full=element('div','related-full article-container');full.innerHTML=page.contentHtml||'';
    panel.appendChild(full);
    if(typeof panel.querySelectorAll==='function'){
      panel.querySelectorAll('pre').forEach(function(pre){
        window.orgMuseumPrepareCodeBlock(pre,pre.querySelector('code'));
      });
    }
  }else panel.appendChild(summaryContent(page, side));
  var open=element('a','related-open','打开完整笔记');open.href=themed(page.href);panel.appendChild(open);
  bindPanelScroll(panel,side==='source'?0:1);
}
function updateMode(nextMode,push){
  document.querySelectorAll('.related-paper').forEach(function(panel,index){positions[mode][index]=panel.scrollTop;});
  mode=nextMode;document.body.dataset.relatedMode=mode;
  if(push)setUrl(mode);
  var srcBtn=document.getElementById('related-open-source');
  if(srcBtn)srcBtn.href=themed(source.href);
  var tgtBtn=document.getElementById('related-open-target');
  if(tgtBtn)tgtBtn.href=themed(target.href);
  document.querySelectorAll('button[data-related-mode]').forEach(function(button){
    var active=button.dataset.relatedMode===mode;button.classList.toggle('is-active',active);
    button.setAttribute('aria-pressed',active?'true':'false');
  });
  renderPanel('source',source);renderPanel('target',target);
  document.querySelectorAll('.related-paper').forEach(function(panel,index){panel.scrollTop=positions[mode][index]||0;});
  setActivePane(activePane);
  if(window.hljs)document.querySelectorAll('.related-full pre code').forEach(function(code){
    var languageClass=Array.from(code.classList).find(function(className){return className.indexOf('language-')===0;});
    var lang=languageClass?languageClass.slice(9):'';
    if(!code.dataset.highlighted&&(!lang||hljs.getLanguage(lang)))hljs.highlightElement(code);
    else if(lang&&!hljs.getLanguage(lang))code.classList.add('no-highlight');
  });
}
function getCompletedPairs(){
  try{return JSON.parse(localStorage.getItem('org-museum-related-completed')||'[]');}catch(e){return [];}
}
function isPairCompleted(sId,tId){
  if(!sId||!tId)return false;
  var list=getCompletedPairs();
  return list.indexOf(sId+'::'+tId)>=0||list.indexOf(tId+'::'+sId)>=0;
}
function togglePairCompleted(sId,tId){
  if(!sId||!tId)return false;
  var list=getCompletedPairs();
  var k1=sId+'::'+tId,k2=tId+'::'+sId;
  var idx=list.indexOf(k1);
  if(idx<0)idx=list.indexOf(k2);
  if(idx>=0){list.splice(idx,1);}else{list.push(k1);}
  try{localStorage.setItem('org-museum-related-completed',JSON.stringify(list));}catch(e){}
  return list.indexOf(k1)>=0||list.indexOf(k2)>=0;
}
function updateCompleteBtnState(btn,done){
  if(!btn)return;
  btn.classList.toggle('is-completed',done);
  btn.setAttribute('aria-pressed',done?'true':'false');
  var icon=btn.querySelector('.complete-icon');
  var text=btn.querySelector('.complete-text');
  if(icon)icon.textContent=done?'✓':'○';
  if(text)text.textContent=done?'已研读 ✓':'标记已读';
}
function renderDetail(){
  if(!links(source,target)&&links(target,source)){var swap=source;source=target;target=swap;}
  index.hidden=true;empty.hidden=true;detail.hidden=false;
  var backShelf=document.getElementById('related-back-shelf');
  if(backShelf){
    backShelf.href=themed('related.html');
    backShelf.onclick=function(e){
      e.preventDefault();
      var url=new URL(location.href);
      url.searchParams.delete('source');url.searchParams.delete('target');url.searchParams.delete('mode');
      history.pushState({},'',url.pathname+url.search+url.hash);
      source=null;target=null;
      renderIndex();
    };
  }
  var bridgeBack=document.getElementById('related-bridge-back');
  if(bridgeBack){
    bridgeBack.href=themed('related.html');
    bridgeBack.onclick=function(e){
      e.preventDefault();
      var url=new URL(location.href);
      url.searchParams.delete('source');url.searchParams.delete('target');url.searchParams.delete('mode');
      history.pushState({},'',url.pathname+url.search+url.hash);
      source=null;target=null;
      renderIndex();
    };
  }
  var both=links(source,target)&&links(target,source);
  var sameCat=(source.categoryLabel||source.category)===(target.categoryLabel||target.category);
  var nexusTag=document.getElementById('related-nexus-tag');
  if(nexusTag)nexusTag.textContent=sameCat?'同主题进阶':'跨领域关联';
  var kindEl=document.getElementById('related-kind');
  if(kindEl)kindEl.textContent=both?'显式 Org 双向链接':'显式 Org 链接';
  var dirEl=document.getElementById('related-direction');
  if(dirEl)dirEl.textContent=both?'源 ↔ 目标':'源 → 目标';
  var swapButton=document.getElementById('related-swap');
  if(swapButton){
    swapButton.hidden=!both;
    if(!swapButton.dataset.bound){
      swapButton.dataset.bound='true';
      swapButton.addEventListener('click',function(){
        var value=source;source=target;target=value;setUrl(mode);
        var srcBtn=document.getElementById('related-open-source');
        if(srcBtn)srcBtn.href=themed(source.href);
        var tgtBtn=document.getElementById('related-open-target');
        if(tgtBtn)tgtBtn.href=themed(target.href);
        renderPanel('source',source);renderPanel('target',target);
        setActivePane(activePane);
        var doneNow=isPairCompleted(source.id,target.id);
        var cBtn=document.getElementById('related-mark-completed');
        if(cBtn)updateCompleteBtnState(cBtn,doneNow);
      });
    }
  }
  var completeBtn=document.getElementById('related-mark-completed');
  if(completeBtn&&source&&target){
    var isDone=isPairCompleted(source.id,target.id);
    updateCompleteBtnState(completeBtn,isDone);
    if(!completeBtn.dataset.bound){
      completeBtn.dataset.bound='true';
      completeBtn.addEventListener('click',function(){
        if(!source||!target)return;
        var next=togglePairCompleted(source.id,target.id);
        updateCompleteBtnState(completeBtn,next);
      });
    }
  }
  document.querySelectorAll('button[data-related-mode]').forEach(function(button){
    if(!button.dataset.bound){
      button.dataset.bound='true';
      button.addEventListener('click',function(){updateMode(button.dataset.relatedMode,true);});
    }
  });
  document.querySelectorAll('button[data-related-pane]').forEach(function(button){
    if(!button.dataset.bound){
      button.dataset.bound='true';
      button.addEventListener('click',function(){setActivePane(button.dataset.relatedPane);});
    }
  });
  var syncButton=document.querySelector('[data-related-sync]');
  if(syncButton&&!syncButton.dataset.bound){
    syncButton.dataset.bound='true';
    syncButton.addEventListener('click',function(){
      syncScroll=!syncScroll;syncButton.classList.toggle('is-active',syncScroll);
      syncButton.setAttribute('aria-pressed',syncScroll?'true':'false');
      syncButton.textContent=syncScroll?'同步滚动：开':'同步滚动：关';
    });
  }
  updateMode(mode,false);
}
var currentGroupMode='category';
var currentCategoryFilter='all';
var currentSearchQuery='';

function createRelatedCard(info){
  var from=info.from,to=info.to;
  var link=element('a','related-index-row');
  link.href=themed('related.html?source='+encodeURIComponent(from.id)+'&target='+encodeURIComponent(to.id)+'&mode=summary');
  link.dataset.search=info.searchTerms;
  link.dataset.sourceCat=info.catFrom;
  link.dataset.targetCat=info.catTo;

  var isDone = isPairCompleted(from.id, to.id);
  if(isDone) link.classList.add('is-completed');

  var cardHeader=element('div','related-index-card-header');
  cardHeader.appendChild(element('span','related-index-number','#'+String(info.position+1).padStart(2,'0')));
  if(isDone){
    cardHeader.appendChild(element('span','related-completed-badge','✓ 已研读'));
  }
  cardHeader.appendChild(element('small','',info.isBidirectional?'双向显式链接':'显式链接'));
  link.appendChild(cardHeader);

  var pair=element('div','related-index-pair');
  var left=element('div','related-index-node');
  left.appendChild(element('span','related-index-cat',info.catFrom));
  left.appendChild(element('strong','related-index-name',from.title));
  pair.appendChild(left);

  var bridge=element('div','related-index-bridge-sign');
  bridge.appendChild(element('span','related-index-arrow',info.isBidirectional?'↔':'→'));
  pair.appendChild(bridge);

  var right=element('div','related-index-node');
  right.appendChild(element('span','related-index-cat',info.catTo));
  right.appendChild(element('strong','related-index-name',to.title));
  pair.appendChild(right);

  link.appendChild(pair);

  var footer=element('div','related-index-card-footer');
  footer.appendChild(element('span','related-index-cta','进入对读 →'));
  link.appendChild(footer);

  link.addEventListener('click',function(e){
    e.preventDefault();
    source=from;target=to;mode='summary';
    setUrl(mode);
    renderDetail();
  });
  return link;
}

function applyFilters(){
  var query=(currentSearchQuery||'').trim().toLowerCase();
  var cat=currentCategoryFilter;
  var visibleTotal=0;
  var list=document.getElementById('related-index-list');
  var noMatchBox=document.getElementById('related-no-match');
  var searchClear=document.getElementById('related-search-clear');
  var matchedStatus=document.getElementById('related-matched-status');
  if(!list)return;

  var sections=list.querySelectorAll('.related-group-section');
  if(sections.length){
    sections.forEach(function(section){
      var cards=Array.from(section.querySelectorAll('.related-index-row'));
      var sectionVisible=0;
      cards.forEach(function(card){
        var matchesSearch=!query||card.dataset.search.includes(query);
        var matchesCat=cat==='all'||card.dataset.sourceCat===cat||card.dataset.targetCat===cat;
        var show=matchesSearch&&matchesCat;
        card.hidden=!show;
        if(show){sectionVisible++;visibleTotal++;}
      });
      section.hidden=sectionVisible===0;
      var badge=section.querySelector('.related-group-badge');
      if(badge)badge.textContent=sectionVisible+' 组关联';
    });
  } else {
    var cards=Array.from(list.querySelectorAll('.related-index-row'));
    cards.forEach(function(card){
      var matchesSearch=!query||card.dataset.search.includes(query);
      var matchesCat=cat==='all'||card.dataset.sourceCat===cat||card.dataset.targetCat===cat;
      var show=matchesSearch&&matchesCat;
      card.hidden=!show;
      if(show)visibleTotal++;
    });
  }

  if(noMatchBox)noMatchBox.hidden=visibleTotal>0||(data.edges||'').length===0;
  if(searchClear)searchClear.hidden=!query;

  if(matchedStatus){
    var total=(data.edges||[]).length;
    var doneCount=0;
    (data.edges||[]).forEach(function(e){if(isPairCompleted(e.source,e.target))doneCount++;});
    var doneSummary=doneCount>0?' · 已完成 '+doneCount+' 组研读':'';
    if(query||cat!=='all'){
      matchedStatus.textContent='匹配 '+visibleTotal+' 组关联（共 '+total+' 组）'+doneSummary;
    } else {
      var catSet=new Set();
      (data.edges||[]).forEach(function(e){
        var f=pages.get(e.source),t=pages.get(e.target);
        if(f)catSet.add(f.categoryLabel||f.category||'未分类');
        if(t)catSet.add(t.categoryLabel||t.category||'未分类');
      });
      matchedStatus.textContent='共 '+total+' 组显式关联 · 覆盖 '+catSet.size+' 个主题分类'+doneSummary;
    }
  }
}

function renderIndex(){
  detail.hidden=true;
  index.hidden=false;
  var edges=data.edges||[];
  empty.hidden=edges.length>0;
  var toolbar=document.getElementById('related-shelf-toolbar');
  if(toolbar)toolbar.hidden=edges.length===0;
  if(edges.length===0)return;

  var edgeInfos=[];
  edges.forEach(function(edge,position){
    var from=pages.get(edge.source),to=pages.get(edge.target);
    if(!from||!to)return;
    var catFrom=from.categoryLabel||from.category||'未分类';
    var catTo=to.categoryLabel||to.category||'未分类';
    var searchTerms=[
      from.title,to.title,catFrom,catTo,
      (from.tags||[]).join(' '), (to.tags||[]).join(' '),
      from.description||'', to.description||''
    ].join(' ').toLowerCase();
    edgeInfos.push({
      edge:edge,
      position:position,
      from:from,
      to:to,
      catFrom:catFrom,
      catTo:catTo,
      isSameCat:catFrom===catTo,
      isBidirectional:!!edge.bidirectional,
      searchTerms:searchTerms
    });
  });

  var pillsContainer=document.getElementById('related-category-pills');
  if(pillsContainer){
    pillsContainer.textContent='';
    var catMap=new Map();
    edgeInfos.forEach(function(info){
      catMap.set(info.catFrom,(catMap.get(info.catFrom)||0)+1);
      if(info.catTo!==info.catFrom){
        catMap.set(info.catTo,(catMap.get(info.catTo)||0)+1);
      }
    });

    var allPill=element('button','related-pill','全部');
    allPill.type='button';
    allPill.dataset.category='all';
    allPill.appendChild(element('span','related-pill-count',String(edgeInfos.length)));
    allPill.classList.toggle('is-active',currentCategoryFilter==='all');
    allPill.setAttribute('aria-pressed',currentCategoryFilter==='all'?'true':'false');
    allPill.addEventListener('click',function(){
      currentCategoryFilter='all';
      pillsContainer.querySelectorAll('.related-pill').forEach(function(btn){
        var active=btn.dataset.category==='all';
        btn.classList.toggle('is-active',active);
        btn.setAttribute('aria-pressed',active?'true':'false');
      });
      applyFilters();
    });
    pillsContainer.appendChild(allPill);

    Array.from(catMap.entries()).sort(function(a,b){
      return b[1]-a[1]||a[0].localeCompare(b[0]);
    }).forEach(function(pair){
      var pill=element('button','related-pill',pair[0]);
      pill.type='button';
      pill.dataset.category=pair[0];
      pill.appendChild(element('span','related-pill-count',String(pair[1])));
      pill.classList.toggle('is-active',currentCategoryFilter===pair[0]);
      pill.setAttribute('aria-pressed',currentCategoryFilter===pair[0]?'true':'false');
      pill.addEventListener('click',function(){
        currentCategoryFilter=pair[0];
        pillsContainer.querySelectorAll('.related-pill').forEach(function(btn){
          var active=btn.dataset.category===pair[0];
          btn.classList.toggle('is-active',active);
          btn.setAttribute('aria-pressed',active?'true':'false');
        });
        applyFilters();
      });
      pillsContainer.appendChild(pill);
    });
  }

  document.querySelectorAll('[data-group-mode]').forEach(function(btn){
    var active=btn.dataset.groupMode===currentGroupMode;
    btn.classList.toggle('is-active',active);
    btn.setAttribute('aria-pressed',active?'true':'false');
    btn.onclick=function(){
      currentGroupMode=btn.dataset.groupMode;
      renderIndex();
    };
  });

  var list=document.getElementById('related-index-list');
  list.textContent='';

  if(currentGroupMode==='category'){
    var groupsMap=new Map();
    edgeInfos.forEach(function(info){
      var groupKey=info.isSameCat?info.catFrom:'__cross__';
      var groupTitle=info.isSameCat?info.catFrom:'跨主题关联';
      var groupDesc=info.isSameCat?'同主题显式对读':'跨领域显式链接';
      if(!groupsMap.has(groupKey)){
        groupsMap.set(groupKey,{key:groupKey,title:groupTitle,desc:groupDesc,items:[]});
      }
      groupsMap.get(groupKey).items.push(info);
    });

    var groupList=Array.from(groupsMap.values()).sort(function(a,b){
      if(a.key==='__cross__')return 1;
      if(b.key==='__cross__')return -1;
      return b.items.length-a.items.length||a.title.localeCompare(b.title);
    });

    groupList.forEach(function(group){
      var section=element('section','related-group-section');
      section.dataset.groupKey=group.key;

      var header=element('div','related-group-header');
      var left=element('div','related-group-header-left');
      left.appendChild(element('span','related-group-indicator',''));
      left.appendChild(element('h2','related-group-title',group.title));
      left.appendChild(element('span','related-group-badge',group.items.length+' 组关联'));
      header.appendChild(left);
      if(group.desc){
        header.appendChild(element('span','related-group-desc',group.desc));
      }
      section.appendChild(header);

      var grid=element('div','related-group-grid');
      group.items.forEach(function(info){
        grid.appendChild(createRelatedCard(info));
      });
      section.appendChild(grid);
      list.appendChild(section);
    });
  } else if(currentGroupMode==='note'){
    var noteGroupsMap=new Map();
    edgeInfos.forEach(function(info){
      var key=info.from.id;
      if(!noteGroupsMap.has(key)){
        noteGroupsMap.set(key,{key:key,title:info.from.title,desc:(info.catFrom)+' · 起始笔记关联',items:[]});
      }
      noteGroupsMap.get(key).items.push(info);
    });

    Array.from(noteGroupsMap.values()).sort(function(a,b){
      return b.items.length-a.items.length||a.title.localeCompare(b.title);
    }).forEach(function(group){
      var section=element('section','related-group-section');
      section.dataset.groupKey=group.key;

      var header=element('div','related-group-header');
      var left=element('div','related-group-header-left');
      left.appendChild(element('span','related-group-indicator',''));
      left.appendChild(element('h2','related-group-title',group.title));
      left.appendChild(element('span','related-group-badge',group.items.length+' 组关联'));
      header.appendChild(left);
      if(group.desc){
        header.appendChild(element('span','related-group-desc',group.desc));
      }
      section.appendChild(header);

      var grid=element('div','related-group-grid');
      group.items.forEach(function(info){
        grid.appendChild(createRelatedCard(info));
      });
      section.appendChild(grid);
      list.appendChild(section);
    });
  } else {
    var grid=element('div','related-group-grid');
    edgeInfos.forEach(function(info){
      grid.appendChild(createRelatedCard(info));
    });
    list.appendChild(grid);
  }

  var shelfSearch=document.getElementById('related-shelf-search');
  var searchClear=document.getElementById('related-search-clear');
  var resetFiltersBtn=document.getElementById('related-reset-filters');

  if(shelfSearch&&!shelfSearch.dataset.bound){
    shelfSearch.dataset.bound='true';
    shelfSearch.addEventListener('input',function(){
      currentSearchQuery=this.value;
      if(search&&search.value!==this.value)search.value=this.value;
      applyFilters();
    });
  }
  if(searchClear&&!searchClear.dataset.bound){
    searchClear.dataset.bound='true';
    searchClear.addEventListener('click',function(){
      currentSearchQuery='';
      if(shelfSearch)shelfSearch.value='';
      if(search)search.value='';
      applyFilters();
    });
  }
  if(resetFiltersBtn&&!resetFiltersBtn.dataset.bound){
    resetFiltersBtn.dataset.bound='true';
    resetFiltersBtn.addEventListener('click',function(){
      currentSearchQuery='';
      currentCategoryFilter='all';
      if(shelfSearch)shelfSearch.value='';
      if(search)search.value='';
      if(pillsContainer){
        pillsContainer.querySelectorAll('.related-pill').forEach(function(btn){
          var active=btn.dataset.category==='all';
          btn.classList.toggle('is-active',active);
          btn.setAttribute('aria-pressed',active?'true':'false');
        });
      }
      applyFilters();
    });
  }
  if(search&&!search.dataset.boundRelated){
    search.dataset.boundRelated='true';
    search.addEventListener('input',function(){
      currentSearchQuery=this.value;
      if(shelfSearch&&shelfSearch.value!==this.value)shelfSearch.value=this.value;
      applyFilters();
    });
  }

  applyFilters();
}
document.addEventListener('click',function(event){
  var link=event.target.closest('a[href]');if(!link||link.href.startsWith('javascript:'))return;
  var raw=link.getAttribute('href')||'';if(raw.startsWith('#'))return;
  link.href=themed(raw);
});
window.addEventListener('keydown',function(event){
  var tag=(event.target&&event.target.tagName)||'';
  if(tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT'||(event.target&&event.target.isContentEditable))return;
  if(event.ctrlKey||event.metaKey||event.altKey)return;
  var isDetail=!detail.hidden;
  if(isDetail){
    if(event.key==='s'||event.key==='S'){
      event.preventDefault();
      updateMode(mode==='summary'?'full':'summary',true);
    }else if(event.key==='y'||event.key==='Y'){
      event.preventDefault();
      var syncBtn=document.querySelector('[data-related-sync]');
      if(syncBtn)syncBtn.click();
    }else if(event.key==='x'||event.key==='X'){
      var swapBtn=document.getElementById('related-swap');
      if(swapBtn&&!swapBtn.hidden){
        event.preventDefault();
        swapBtn.click();
      }
    }else if(event.key==='Escape'){
      event.preventDefault();
      var backBtn=document.getElementById('related-back-shelf');
      if(backBtn)backBtn.click();
    }
  }else{
    if(event.key==='/'||event.key==='f'||event.key==='F'){
      var shelfInput=document.getElementById('related-shelf-search');
      if(shelfInput){
        event.preventDefault();
        shelfInput.focus();
        shelfInput.select();
      }
    }
  }
});
window.addEventListener('popstate',function(){
  var p=new URLSearchParams(location.search);
  source=pages.get(p.get('source')||'');
  target=pages.get(p.get('target')||'');
  mode=p.get('mode')==='full'?'full':'summary';
  if(relationValid())renderDetail();else renderIndex();
});
if(relationValid())renderDetail();else renderIndex();
})();

